function renderUI(){if(!scene)return;locale?.invalidate();renderHeader();renderStory();renderCamera();renderFooter();applyLanguage();}
function observe(id,assisted=false){const c=chapter();if(!c.observations?.some(o=>o.id===id))return;state.seen[c.id]??=[];if(!state.seen[c.id].includes(id)){state.seen[c.id].push(id);action('observe',{observationId:id},assisted);}selectedObservation=id;renderStory();applyLanguage();}
function choose(id,assisted=false){const c=chapter();if(!c.choices?.some(x=>x.id===id)||(state.seen[c.id]||[]).length<(c.observations||[]).length)return;state.decisions[c.id]={choiceId:id,assisted,roleId:state.roleId};action('decision',{choiceId:id},assisted);renderStory();applyLanguage();}
function advance(assisted=false){const c=chapter(),seen=state.seen[c.id]||[];if(seen.length<(c.observations||[]).length||((c.choices||[]).length&&!state.decisions[c.id]))return;const wasAll=state.completed.length===scene.chapters.length;if(!state.completed.includes(c.id))state.completed.push(c.id);action('complete',{},assisted);if(wasAll){visitChapter(scene.chapters[0].id);return;}const choice=c.choices?.find(x=>x.id===state.decisions[c.id]?.choiceId),next=scene.chapters.find(x=>x.id===(choice?.next||choice?.nextChapterId))||scene.chapters[scene.chapters.indexOf(c)+1];if(next)visitChapter(next.id);else{renderStory();renderFooter();applyLanguage();toast(L('故事旅程完成；可匯出紀錄或換個角色再看。','Journey complete. Export your record or explore another role.'));}}
function visitChapter(id){const c=scene.chapters.find(x=>x.id===id);if(!c)return;stopAssist();state.chapterId=id;selectedObservation='';selectedEquipment='';action('visit');if(c.assetId&&assetById(c.assetId))loadAsset(assetById(c.assetId));renderUI();tutor?.refresh();}
function assist(){stopAssist();const epoch=assistEpoch,c=chapter(),id=c.id;storyOpen=true;let i=0;const items=c.observations||[];function next(){if(epoch!==assistEpoch||chapter()?.id!==id)return;if(i<items.length){observe(items[i++].id,true);assistTimer=setTimeout(next,900);return;}if(c.choices?.length)choose((c.choices.find(x=>x.recommended===true)||c.choices[0]).id,true);action('mentor-demonstration',{},true);renderStory();applyLanguage();toast(L('師傅已示範本章，請閱讀結果後按「完成本章」。','The mentor demonstrated this chapter. Read the outcome, then complete the chapter.'));}next();}
function narrate(){const c=chapter(),text=[field(c,'title'),field(role(),'perspective'),field(c,'description'),chapterTask(c)].filter(Boolean).join('。');if(!root.speechSynthesis||!root.SpeechSynthesisUtterance){toast(L('此裝置沒有語音，請閱讀畫面文字。','Speech is unavailable; read the on-screen text.'));return;}stopAssist();const utter=new SpeechSynthesisUtterance(text);utter.lang=zh()?'zh-TW':'en';utter.rate=.95;speechSynthesis.speak(utter);if(!['zh-TW','en'].includes(language()))toast(L('此段朗讀使用英文原文。','This narration uses the authored English text.'));}
function showEquipment(id){selectedEquipment=id;storyOpen=true;action('equipment',{equipmentId:id});renderStory();applyLanguage();$('#xp-story details')?.setAttribute('open','');}
function showHUD(show){hudHidden=!show;$('#xp-interface').hidden=!show;$('#xp-restore-hud').hidden=show;}$('#xp-restore-hud').onclick=()=>showHUD(true);
function openDialog(selector){const d=$(selector);lastFocus=document.activeElement;if(d.showModal)d.showModal();else d.setAttribute('open','');applyLanguage(d);const first=d.querySelector('input,button,select');first?.focus();}
